function ruleR5(counting) {
  for (let c = 0; c < NC; c += 1) {
    if (covered[c] === 1) {
      continue;
    }
    let P = -1;
    let one = true;
    const to = colStart[c + 1];
    for (let k = colStart[c]; k < to; k += 1) {
      work += 1;
      const r = colRows[k];
      if (live[r] === 0) {
        continue;
      }
      if (P === -1) {
        P = rowPiece[r];
      } else if (rowPiece[r] !== P) {
        one = false;
        break;
      }
    }
    if (!one || P === -1) {
      continue;
    }
    let killed = 0;
    const pieceTo = colStart[NC + P + 1];
    for (let k = colStart[NC + P]; k < pieceTo; k += 1) {
      work += 1;
      const r = colRows[k];
      if (live[r] === 0) {
        continue;
      }
      let covers = false;
      const end = rowStart[r + 1] - 1;
      for (let j = rowStart[r]; j < end && !covers; j += 1) {
        work += 1;
        covers = rowCols[j] === c;
      }
      if (!covers) {
        kill(r);
        killed += 1;
      }
    }
    if (killed > 0) {
      if (counting) {
        rules[4] += killed;
      }
      return APPLIED;
    }
  }
  return NONE;
}

